const crypto = require('crypto');

// Sumber kebenaran jenis produk = SKU, sama persis dengan mu-plugin cetak.php
// dan WF-01. Jangan menebak dari nama produk (pelajaran bug tier F3.2).
function jenisItem(li) {
  const sku = String(li.sku || '').toUpperCase();
  if (sku.startsWith('HARIH-')) return 'digital';
  if (sku.startsWith('CETAK-') || sku.startsWith('UPG-')) return 'hybrid';
  if (sku.startsWith('SATUAN-')) return 'satuan';
  return /hemat|favorit|premium/i.test(String(li.name || '')) ? 'digital' : 'satuan';
}

function normalisasiWa(input) {
  let d = String(input || '').replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('0')) d = '62' + d.slice(1);
  else if (d.startsWith('620')) d = '62' + d.slice(3);
  else if (d.startsWith('8')) d = '62' + d;
  if (!d.startsWith('62') || d.length < 10 || d.length > 15) return '';
  return d;
}

const semua = $input.all().map((i) => i.json).filter((o) => o && o.id);

// Pembeli yang PERNAH memesan cetak tidak boleh ditawari lagi — dicek lintas
// seluruh riwayat 40 hari, dikunci pada nomor WA & email (satu orang bisa
// memesan dua kali dengan email berbeda).
const sudahCetak = new Set();
for (const o of semua) {
  const punyaCetak = (o.line_items || []).some((li) => ['hybrid', 'satuan'].includes(jenisItem(li)));
  if (!punyaCetak) continue;
  const wa = normalisasiWa((o.billing || {}).phone);
  const em = String((o.billing || {}).email || '').toLowerCase();
  if (wa) sudahCetak.add('wa:' + wa);
  if (em) sudahCetak.add('em:' + em);
}

const HARI_MS = 86400000;
const hariIni = new Date(new Date().toISOString().slice(0, 10) + 'T00:00:00Z').getTime();
const keluar = [];

for (const o of semua) {
  const items = o.line_items || [];
  if (!items.length) continue;

  // Hanya pembeli DIGITAL murni — yang sudah beli cetak tidak ditawari apa pun.
  const semuaDigital = items.every((li) => jenisItem(li) === 'digital');
  if (!semuaDigital) continue;

  const wa = normalisasiWa((o.billing || {}).phone);
  const em = String((o.billing || {}).email || '').toLowerCase();
  if (!wa) continue;
  if (sudahCetak.has('wa:' + wa) || sudahCetak.has('em:' + em)) continue;

  const dibayar = o.date_paid_gmt || o.date_created_gmt || '';
  if (!dibayar) continue;
  const tglBayar = new Date(dibayar.slice(0, 10) + 'T00:00:00Z').getTime();
  const umur = Math.round((hariIni - tglBayar) / HARI_MS);

  // Dua ketukan saja: H+3 (masih hangat) dan H+12 (dua hari sebelum kredit
  // 14 hari habis). Lebih dari itu berubah jadi gangguan, bukan pengingat.
  if (umur !== 3 && umur !== 12) continue;

  if (!$env.FORM_TOKEN_SECRET) throw new Error('Env FORM_TOKEN_SECRET belum di-set di container n8n');
    // B9 — link ini menuju /upsell/, jadi cakupannya HARUS 'upsell'.
  const token = crypto.createHmac('sha256', $env.FORM_TOKEN_SECRET).update(String(o.id) + '|upsell').digest('hex').slice(0, 16);
  const link = `${$env.WP_URL}/upsell/?order=${o.id}&key=${token}`;
  const namaDepan = (o.billing || {}).first_name || 'Kak';
  const sisaHari = 14 - umur;

  const teks = umur === 3
    ? `Halo ${namaDepan} 🤍\n\nUndangan digitalmu sudah tayang. Satu hal yang sering ditanyakan pemesan lain: *bagaimana dengan orang tua dan sesepuh yang kurang terbiasa dengan HP?*\n\nUntuk mereka ada undangan cetak lipat beserta amplop bernama tamu — desainnya sama persis dengan undangan digitalmu, dikerjakan dari data yang sudah kamu isi. Yang sudah kamu bayar dihitung sebagai kredit (berlaku ${sisaHari} hari lagi):\n${link}\n\nKalau tidak perlu, abaikan saja pesan ini ya 🙏\n— hariH`
    : `Halo ${namaDepan} 🤍\n\nPengingat singkat: kredit untuk naik ke paket cetak *berakhir ${sisaHari} hari lagi*.\n\nUndangan cetak lipat + amplop bernama tamu untuk orang tua & sesepuh, desain sama dengan undangan digitalmu:\n${link}\n\nSetelah itu harga kembali normal. Ini pengingat terakhir dari kami 🙏\n— hariH`;

  keluar.push({ json: { order_id: String(o.id), nama_depan: namaDepan, wa, umur, sisa_hari: sisaHari, link, teks } });
}

return keluar;
